#[test]
fn an_unrepresentable_instance_refuses_before_processes_or_state_mutations() {
    let home = tempfile::tempdir().unwrap();
    let calls = home.path().join("called");
    for name in ["docker", "ssh"] {
        let fake = home.path().join(name);
        std::fs::write(
            &fake,
            "#!/bin/sh\ntouch \"$INSTANCE_REFUSAL_CALLS\"\nexit 99\n",
        )
        .unwrap();
        std::fs::set_permissions(&fake, std::fs::Permissions::from_mode(0o700)).unwrap();
    }
    for remote in [false, true] {
        let root = home.path().join(if remote { "remote" } else { "local" });
        let mut command = Command::new(env!("CARGO_BIN_EXE_router"));
        command.args([
            "deploy",
            "--instance",
            &"a".repeat(33),
            "--root",
            root.to_str().unwrap(),
        ]);
        if remote {
            command.args(["--server", "fixture@example.test"]);
        }
        let output = command
            .env("HOME", home.path())
            .env("CLAUDE_CONFIG_DIR", home.path().join(".claude"))
            .env("DATA_DIR", home.path().join("client-state"))
            .env("TOKEN_SECRET", "instance-refusal-fixture")
            .env("INSTANCE_REFUSAL_CALLS", &calls)
            .env(
                "PATH",
                format!(
                    "{}:{}",
                    home.path().display(),
                    std::env::var("PATH").unwrap()
                ),
            )
            .output()
            .unwrap();
        assert!(!output.status.success());
        assert!(String::from_utf8_lossy(&output.stderr).contains("1-32"));
        assert!(
            !calls.exists(),
            "refused instance invoked a deployment process"
        );
        assert!(!root.exists(), "refused instance created deployment state");
    }
}

#[test]
fn an_unpublished_default_image_refuses_local_and_staging_plans_without_writes() {
    let home = tempfile::tempdir().unwrap();
    let docker = home.path().join("docker");
    std::fs::write(&docker, "#!/bin/sh\ncase \"$1\" in info) echo 28; exit 0;; ps) exit 0;; esac\necho 'manifest unknown' >&2\nexit 1\n").unwrap();
    std::fs::set_permissions(&docker, std::fs::Permissions::from_mode(0o700)).unwrap();
    for staging in [false, true] {
        let root = home.path().join(if staging { "staging" } else { "local" });
        let mut command = Command::new(env!("CARGO_BIN_EXE_router"));
        command.args(["deploy", "--root", root.to_str().unwrap()]);
        if staging {
            command.args(["--staging", "image-preflight"]);
        } else {
            command.arg("--status");
        }
        let output = command
            .env("HOME", home.path())
            .env("DATA_DIR", home.path().join("data"))
            .env(
                "PATH",
                format!(
                    "{}:{}",
                    home.path().display(),
                    std::env::var("PATH").unwrap()
                ),
            )
            .env("TOKEN_SECRET", "image-preflight-secret")
            .env("RUST_LOG", "error")
            .output()
            .unwrap();
        let rendered = format!(
            "{}{}",
            String::from_utf8_lossy(&output.stdout),
            String::from_utf8_lossy(&output.stderr)
        );
        assert!(!output.status.success(), "{rendered}");
        assert!(rendered.contains("image-unpublished"), "{rendered}");
        assert!(
            rendered.contains(&format!(
                "image for {} is not published",
                link_assistant_router::VERSION
            )),
            "{rendered}"
        );
        assert!(rendered.contains("pass --image"), "{rendered}");
        assert!(!rendered.contains("plan step="), "{rendered}");
        assert!(!root.exists(), "preflight must not create deployment state");
    }
}

#[test]
fn an_explicit_build_does_not_require_a_published_default_image() {
    let home = tempfile::tempdir().unwrap();
    let docker = home.path().join("docker");
    std::fs::write(&docker, "#!/bin/sh\nprintf '%s\\n' \"$1\" >> \"$IMAGE_PREFLIGHT_CALLS\"\ncase \"$1\" in info) echo 28; exit 0;; ps) exit 0;; manifest) echo 'manifest unknown' >&2;; esac\nexit 1\n").unwrap();
    std::fs::set_permissions(&docker, std::fs::Permissions::from_mode(0o700)).unwrap();
    for staging in [false, true] {
        let root = home.path().join(if staging { "staging" } else { "local" });
        let calls = home.path().join(if staging {
            "staging-calls"
        } else {
            "local-calls"
        });
        let mut command = Command::new(env!("CARGO_BIN_EXE_router"));
        command.args(["deploy", "--root", root.to_str().unwrap(), "--build", "."]);
        if staging {
            command.args(["--staging", "build-preflight"]);
        } else {
            command.arg("--status");
        }
        let output = command
            .env("HOME", home.path())
            .env("DATA_DIR", home.path().join("data"))
            .env("IMAGE_PREFLIGHT_CALLS", &calls)
            .env(
                "PATH",
                format!(
                    "{}:{}",
                    home.path().display(),
                    std::env::var("PATH").unwrap()
                ),
            )
            .env("TOKEN_SECRET", "image-preflight-secret")
            .env("RUST_LOG", "error")
            .output()
            .unwrap();
        let rendered = format!(
            "{}{}",
            String::from_utf8_lossy(&output.stdout),
            String::from_utf8_lossy(&output.stderr)
        );
        assert!(!rendered.contains("image-unpublished"), "{rendered}");
        let calls = std::fs::read_to_string(calls).unwrap();
        assert!(!calls.lines().any(|call| call == "manifest"), "{calls}");
        if staging {
            assert!(
                root.join("staging.json").exists(),
                "the explicit build reaches staging execution: {rendered}"
            );
        }
    }
}

